<script lang="ts">
 import {onDestroy} from 'svelte';import {reportEditorDirty} from './editor-drafts';import {uid,type Project,type Account} from './model';import {saveAccountDocument,unpostAccountDocument,markAccountDocument,type AccountDocument} from './account-lifecycle';import {makeAccountDocument,residentsAt,servicesAt,holderAt,accountProperty,propertyDetails,statusLabel} from './account-data';import {monthlyPersons} from './occupancy';import {displayDate} from './date-format';import {translator} from './i18n';import type {ReferenceKind} from './catalog-definitions';import RecordToolbar from './RecordToolbar.svelte';import LineToolbar from './LineToolbar.svelte';import AccountLookupField from './AccountLookupField.svelte';import {openReportLookup} from './report-settings';import {Check,Save,X,FileText} from '@lucide/svelte';
 export let editorId='';export let project:Project;export let kind:AccountDocument['kind'];export let initial:AccountDocument|null=null;export let onapply:(p:Project)=>void;export let onedit:(d:AccountDocument)=>void;export let onclose:()=>void;export let onreference:(kind:string,id:string)=>void;export let onmovements:(d:AccountDocument)=>void;export let beforeChange:(id:string)=>Promise<boolean>=async()=>true;
 let draft=initial?structuredClone(initial):null,selected='',selectedRow='',tab='main',query='',filterOpen=false,error='',fillService=project.services[0]?.id||'';
 $:t=translator(project.settings.language);$:locked=draft?.state==='applied'||!!draft?.imported;$:documents=project.account_documents.filter(d=>d.kind===kind&&(d.number+' '+d.account.number+' '+d.account.payer_name+' '+d.comment+' '+d.date).toLocaleLowerCase().includes(query.toLocaleLowerCase()));$:current=documents.find(d=>d.id===selected);
 $:tabs=kind==='open'?[['main','Основное','Principal'],['residents','Проживающие','Locatari'],['services','Услуги','Servicii'],['additional','Дополнительные объекты учёта','Obiecte suplimentare'],['characteristics','Параметры расчёта','Parametri de calcul']]:kind==='information'?[['main','Основное','Principal'],['services','Услуги','Servicii'],['additional','Дополнительные объекты учёта','Obiecte suplimentare'],['characteristics','Параметры расчёта','Parametri de calcul']]:kind==='opening-balance'?[['balances','Сальдо по услугам','Sold pe servicii'],['readings','Показания приборов учёта','Indexuri contoare']]:[];
 $: {if(kind==='services')tab='services';else if(kind==='residents')tab='residents';else if(kind==='additional')tab='additional';else if(kind==='characteristics')tab='custom';else if(kind==='opening-balance'&&tab==='main')tab='balances';}
 let savedDraft=JSON.stringify(draft);
 $: hasDraftChanges = !!draft && !locked && (!project.account_documents.some(d=>d.id===draft?.id) || JSON.stringify(draft)!==savedDraft);
 $: reportEditorDirty(editorId,hasDraftChanges);
 onDestroy(()=>reportEditorDirty(editorId,false));

 function create(){onedit(makeAccountDocument(project,kind));}
 function copyDocument(){if(!current)return;const copy=makeAccountDocument(project,kind,kind==='open'?undefined:project.accounts.find(a=>a.id===current.account.id));copy.comment=current.comment;copy.service_rows=current.service_rows?.map(r=>({...r,id:uid(),account_id:kind==='open'?copy.account.id:r.account_id,date:copy.date}));copy.resident_rows=current.resident_rows?.map(r=>({...r,id:uid()}));copy.additional_rows=current.additional_rows?.map(r=>({...r,id:uid()}));copy.characteristic_rows=current.characteristic_rows?.map(r=>({...r,id:uid()}));onedit(copy);}
 async function action(command:'post'|'unpost'|'mark'){if(!current)return;const id=current.id;try{if(!(await beforeChange(id)))return;const doc=project.account_documents.find(d=>d.id===id)!;onapply(command==='post'?saveAccountDocument(project,doc,true):command==='unpost'?unpostAccountDocument(project,id):markAccountDocument(project,id));error='';}catch(e){error=e instanceof Error?e.message:String(e);}}
 function selectAccount(id:string){const a=project.accounts.find(a=>a.id===id);if(!a||!draft)return;const holder=holderAt(project,a,draft.date);draft={...draft,account:{...structuredClone(a),payer_name:holder.name,holder_id:holder.id,registration_enabled:a.registration_enabled??true,residents_enabled:a.residents_enabled??true,waste_charge_persons:monthlyPersons(project,a,draft.date.slice(0,7)).persons??a.waste_charge_persons}};}
 function property(id:string){if(!draft)return;if(kind==='residents'){const account=project.accounts.find(a=>accountProperty(a)===id);if(!account){error=t('Для объекта не найден лицевой счёт.','Nu s-a găsit un cont pentru obiect.');return;}selectAccount(account.id);}const record=project.reference_catalogs.properties?.find(p=>p.id===id);draft.account.property_id=id;draft.account.custom_fields.property_id=id;if(record){draft.account.address=record.name;draft.account.apartments=[record.attributes.number||''].filter(Boolean);draft.account.total_area_m2=record.attributes.total_area||draft.account.total_area_m2;draft.account.living_area_m2=record.attributes.living_area||'0';draft.account.floor=record.attributes.floor||'';}}
 function holder(id:string){if(!draft)return;draft.account.holder_id=id;draft.account.payer_name=project.reference_catalogs.citizens?.find(c=>c.id===id)?.name||'';}
 function key(){return tab==='services'?'service_rows':tab==='residents'?'resident_rows':tab==='additional'?'additional_rows':tab==='balances'?'balance_rows':tab==='readings'?'initial_readings':'characteristic_rows';}
 function add(){if(!draft)return;const id=uid();if(tab==='services')draft.service_rows=[...(draft.service_rows||[]),{id,account_id:draft.account.id,service_id:fillService,tariff_type_id:project.reference_catalogs['tariff-types']?.find(r=>r.attributes.service_id===fillService)?.id||'',date:draft.date,active:true}];else if(tab==='residents')draft.resident_rows=[...(draft.resident_rows||[]),{id,citizen_id:'',registration:2,residence:2,from:draft.date,to:null}];else if(tab==='additional')draft.additional_rows=[...(draft.additional_rows||[]),{id,property_id:'',active:true}];else if(tab==='balances')draft.balance_rows=[...(draft.balance_rows||[]),{id,service_id:fillService,amount:'0.00',penalty:'0.00'}];else if(tab==='readings')draft.initial_readings=[...(draft.initial_readings||[]),{id,meter_id:project.meters.find(m=>m.account_id===draft!.account.id&&m.scope==='individual')?.id||'',value:'0',date:draft.date}];else draft.characteristic_rows=[...(draft.characteristic_rows||[]),{id,name:'',value:''}];selectedRow=id;}
 function modify(mode:'remove'|'copy'|'clear'|number){if(!draft)return;const field=key(),rows=[...(draft[field]||[])] as {id:string}[],i=rows.findIndex(r=>r.id===selectedRow);if(mode==='clear')rows.length=0;else if(mode==='remove'&&i>=0)rows.splice(i,1);else if(mode==='copy'&&i>=0){const copy={...structuredClone(rows[i]),id:uid()};rows.splice(i+1,0,copy);selectedRow=copy.id;}else if(typeof mode==='number'&&i>=0&&i+mode>=0&&i+mode<rows.length)[rows[i],rows[i+mode]]=[rows[i+mode],rows[i]];(draft as unknown as Record<string,unknown>)[field]=rows;}
 function fill(ids?:string[]){if(!draft)return;if(tab==='services'){const accounts=kind==='services'?(ids?project.accounts.filter(a=>ids.includes(a.id)):project.accounts.filter(a=>a.active)):[draft.account];for(const a of accounts){if(kind==='services'){if(!draft.service_rows?.some(r=>r.account_id===a.id&&r.service_id===fillService))draft.service_rows=[...(draft.service_rows||[]),{id:uid(),account_id:a.id,service_id:fillService,tariff_type_id:project.reference_catalogs['tariff-types']?.find(r=>r.attributes.service_id===fillService)?.id||'',date:draft.date,active:true}];}else for(const s of project.services.filter(s=>ids?ids.includes(s.id):s.active))if(!draft.service_rows?.some(r=>r.service_id===s.id))draft.service_rows=[...(draft.service_rows||[]),{id:uid(),account_id:a.id,service_id:s.id,tariff_type_id:project.reference_catalogs['tariff-types']?.find(r=>r.attributes.service_id===s.id)?.id||'',date:draft.date,active:true}];}}
 else if(tab==='additional'){for(const id of ids||[])if(!draft.additional_rows?.some(r=>r.property_id===id))draft.additional_rows=[...(draft.additional_rows||[]),{id:uid(),property_id:id,active:true}];}
 else if(tab==='residents'){const a=project.accounts.find(a=>a.id===draft!.account.id)||project.accounts.find(a=>accountProperty(a)===accountProperty(draft!.account));const rows=ids?ids.map(id=>({id,registration:2,residence:2,from:draft!.date,to:null})):a?residentsAt(project,a,draft.date):[];for(const row of rows)if(!draft.resident_rows?.some(r=>r.citizen_id===row.id))draft.resident_rows=[...(draft.resident_rows||[]),{id:uid(),citizen_id:row.id,registration:row.registration,residence:row.residence,from:row.from||draft.date,to:row.to}];}
 else if(tab==='additional'&&ids){for(const id of ids)if(!draft.additional_rows?.some(r=>r.property_id===id))draft.additional_rows=[...(draft.additional_rows||[]),{id:uid(),property_id:id,active:true}];}
 else if(tab==='balances'){for(const service of project.services.filter(s=>ids?ids.includes(s.id):draft!.account.service_ids.includes(s.id)))if(!draft.balance_rows?.some(r=>r.service_id===service.id))draft.balance_rows=[...(draft.balance_rows||[]),{id:uid(),service_id:service.id,amount:'0.00',penalty:'0.00'}];}
 else if(tab==='readings'){for(const meter of project.meters.filter(m=>m.account_id===draft!.account.id&&m.scope==='individual'))if(!draft.initial_readings?.some(r=>r.meter_id===meter.id))draft.initial_readings=[...(draft.initial_readings||[]),{id:uid(),meter_id:meter.id,value:meter.initial_value||'0',date:draft.date}];}}
 function fillCommand(){if(kind==='services'&&tab==='services')openReportLookup({id:editorId+'-fill-service',parentId:editorId,label:t('Услуга для заполнения','Serviciu pentru completare'),kind:'services',items:[],selected:[],multiple:false,onchoose:ids=>{fillService=ids[0]||'';if(fillService&&!locked)fill();}});else fill();}
 function pick(){const kind=tab==='residents'?'citizens':tab==='additional'?'properties':tab==='services'&&draft?.kind==='services'?'accounts':'services';openReportLookup({id:editorId+'-'+tab,parentId:editorId,label:t('Выбор элементов','Selectare elemente'),kind,items:[],selected:[],multiple:true,onchoose:ids=>{if(!locked)fill(ids);}});}
 function save(post=false,close=false){if(!draft)return;try{const next=saveAccountDocument(project,draft,post);onapply(next);draft=structuredClone(next.account_documents.find(d=>d.id===draft!.id)!);savedDraft=JSON.stringify(draft);reportEditorDirty(editorId,false);error='';if(close)onclose();}catch(e){error=e instanceof Error?e.message:String(e);}}
</script>
<div class="account-documents">{#if error}<p class="alert error" role="alert">{error}</p>{/if}
{#if !draft}<RecordToolbar language={project.settings.language} selected={!!current} onadd={create} oncopy={copyDocument} onedit={()=>current&&onedit(structuredClone(current))} onremove={()=>action('mark')} onrefresh={()=>selected=''} onfilter={()=>filterOpen=!filterOpen} onclearfilter={()=>query=''} filterActive={!!query} onpost={()=>action('post')} canPost={current?.state==='draft'&&!current.imported&&!current.marked_for_deletion} onunpost={()=>action('unpost')} canUnpost={current?.state==='applied'&&!current.imported&&!!current.before_history} onmovements={()=>current&&onmovements(current)}/>{#if filterOpen}<label>{t('Отбор','Filtrare')}<input bind:value={query}/></label>{/if}<div class="table-wrap"><table><thead><tr><th>{t('Дата','Data')}</th><th>{t('Номер','Număr')}</th>{#if kind!=='services'&&kind!=='residents'}<th>{t('Лицевой счёт','Cont personal')}</th>{/if}<th>{t('Комментарий','Comentariu')}</th><th>{t('Статус','Stare')}</th></tr></thead><tbody>{#each documents as doc}<tr class:selected={selected===doc.id} class:marked={doc.marked_for_deletion} class:attention-row={doc.state==='draft'} onclick={()=>selected=doc.id} ondblclick={()=>onedit(structuredClone(doc))}><td>{displayDate(doc.date,project)}</td><td>{doc.number}</td>{#if kind!=='services'&&kind!=='residents'}<td>{doc.account.number} · {doc.account.payer_name}</td>{/if}<td>{doc.comment}</td><td>{doc.marked_for_deletion?t('Помечен на удаление','Marcat pentru ștergere'):doc.state==='applied'?t('Проведён','Aplicat'):t('Черновик','Ciornă')}</td></tr>{/each}</tbody></table></div>
{:else}
 <fieldset disabled={locked}><div class="document-date"><label>{t('Дата','Data')}<input type="date" bind:value={draft.date}/></label></div>
 {#if kind==='close'||kind==='opening-balance'||kind==='additional'||kind==='characteristics'}<label class="field"><span>{t('Лицевой счёт:','Cont personal:')}</span><AccountLookupField {project} parentId={editorId} kind="accounts" value={draft.account.id} clearable={false} onselect={selectAccount} oninspect={id=>onreference('accounts',id)}/></label>{/if}
 {#if kind==='residents'}<div class="resident-flags"><label class="check-row"><input type="checkbox" bind:checked={draft.account.registration_enabled}/>{t('Регистрационный учёт','Evidența înregistrării')}</label><label class="check-row"><input type="checkbox" bind:checked={draft.account.residents_enabled}/>{t('Учёт проживающих','Evidența locatarilor')}</label></div><label class="field"><span>{t('Объект учёта:','Obiect:')}</span><AccountLookupField {project} parentId={editorId} kind="properties" value={accountProperty(draft.account)} clearable={false} onselect={property} oninspect={id=>onreference('properties',id)}/></label>{/if}
 {#if kind==='opening-balance'}<label class="field">{t('Сумма аванса:','Avans:')}<input bind:value={draft.advance}/></label>{#if Number(draft.advance)>0}<label class="field">{t('Услуга для аванса:','Serviciul avansului:')}<AccountLookupField {project} parentId={editorId} kind="services" value={draft.advance_service_id||''} onselect={id=>{if(draft)draft.advance_service_id=id;}}/></label>{/if}{/if}
 </fieldset>
 {#if tabs.length}<nav class="tabs">{#each tabs as item}<button class:chosen={tab===item[0]} onclick={()=>{tab=item[0];selectedRow='';}}>{project.settings.language==='ru'?item[1]:item[2]}</button>{/each}</nav>{/if}
 {#if tab==='main'&&(kind==='open'||kind==='information')}<fieldset disabled={locked}>
 {#if kind==='open'}<label class="check-row"><input type="checkbox" bind:checked={draft.account.registration_enabled}/>{t('Регистрационный учёт','Evidența înregistrării')}</label><label class="check-row"><input type="checkbox" bind:checked={draft.account.residents_enabled}/>{t('Учёт проживающих','Evidența locatarilor')}</label><label class="field"><span>{t('Объект учёта:','Obiect:')}</span><AccountLookupField {project} parentId={editorId} kind="properties" value={accountProperty(draft.account)} onselect={property} oninspect={id=>onreference('properties',id)}/></label>
 {:else}<label class="field"><span>{t('Лицевой счёт:','Cont personal:')}</span><AccountLookupField {project} parentId={editorId} kind="accounts" value={draft.account.id} clearable={false} onselect={selectAccount} oninspect={id=>onreference('accounts',id)}/></label><label class="check-row"><input type="checkbox" bind:checked={draft.change_holder}/>{t('Изменить ответственного квартиросъёмщика','Schimbă titularul responsabil')}</label><label class="field"><span>{t('Предыдущий ответственный:','Titular precedent:')}</span><input readonly value={draft.before?.payer_name||project.accounts.find(a=>a.id===draft!.account.id)?.payer_name||''}/></label>{/if}
 <label class="field"><span>{kind==='information'?t('Новый ответственный:','Titular nou:'):t('Ответственный квартиросъёмщик:','Titular responsabil:')}</span><AccountLookupField {project} parentId={editorId} kind="citizens" disabled={locked||kind==='information'&&draft.change_holder===false} value={draft.account.holder_id||''} text={draft.account.payer_name} onselect={holder} oninspect={id=>onreference('citizens',id)}/></label>{#if kind==='open'}<label class="field"><span>{t('Номер лицевого счёта:','Număr cont personal:')}</span><input bind:value={draft.account.number}/></label>{/if}</fieldset>
 {:else if tab==='characteristics'}<fieldset disabled={locked}><div class="field-grid"><label>{t('Адрес','Adresă')}<input bind:value={draft.account.address}/></label><label>{t('Общая площадь, м²','Suprafață totală, m²')}<input bind:value={draft.account.total_area_m2}/></label><label>{t('Жилая площадь, м²','Suprafață locuibilă, m²')}<input bind:value={draft.account.living_area_m2}/></label><label>{t('Этаж','Etaj')}<input bind:value={draft.account.floor}/></label><label>{t('Количество зарегистрированных','Număr persoane înregistrate')}<input type="number" min="0" bind:value={draft.account.registered_residents}/></label><label>{t('Людей для платы за мусор в месяце документа','Locatari pentru deșeuri în luna documentului')}<input type="number" min="0" bind:value={draft.account.waste_charge_persons}/></label></div></fieldset>
 {:else if kind!=='close'}
 <LineToolbar language={project.settings.language} disabled={locked} selected={!!selectedRow} onadd={add} oncopy={()=>modify('copy')} onremove={()=>modify('remove')} onmove={d=>modify(d)} onpick={tab==='custom'||tab==='readings'?undefined:pick} onfill={tab==='custom'||tab==='additional'?undefined:fillCommand} onclear={()=>modify('clear')}/>

 <div class="table-wrap"><table><thead><tr><th>№</th>{#if tab==='services'}{#if kind==='services'}<th>{t('Лицевой счёт','Cont personal')}</th>{/if}<th>{t('Услуга','Serviciu')}</th><th>{t('Вид тарифа','Tip tarif')}</th><th>{t('Дата изменения','Data modificării')}</th><th>{t('Статус','Stare')}</th>{:else if tab==='residents'}<th>{t('Гражданин','Cetățean')}</th><th>{t('Вид регистрации','Tip înregistrare')}</th><th>{t('Статус проживания','Stare locuire')}</th><th>{t('Дата начала','Data începerii')}</th><th>{t('Дата окончания','Data încheierii')}</th>{:else if tab==='additional'}<th>{t('Объект учёта','Obiect')}</th><th>{t('Статус','Stare')}</th>{:else if tab==='balances'}<th>{t('Услуга','Serviciu')}</th><th>{t('Сумма','Sumă')}</th><th>{t('Сумма пени','Penalitate')}</th>{:else if tab==='readings'}<th>{t('Индивидуальный прибор учёта','Contor individual')}</th><th>{t('Показание','Index')}</th><th>{t('Дата показания','Data indexului')}</th>{:else}<th>{t('Характеристика','Caracteristică')}</th><th>{t('Значение','Valoare')}</th>{/if}</tr></thead><tbody>
 {#if tab==='services'}{#each draft.service_rows||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td>{#if kind==='services'}<td><AccountLookupField {project} parentId={editorId} kind="accounts" value={row.account_id} disabled={locked} clearable={false} onselect={id=>row.account_id=id}/></td>{/if}<td><AccountLookupField {project} parentId={editorId} kind="services" value={row.service_id} disabled={locked} clearable={false} onselect={id=>{row.service_id=id;row.tariff_type_id=project.reference_catalogs['tariff-types']?.find(r=>r.attributes.service_id===id)?.id||'';}}/></td><td><AccountLookupField {project} parentId={editorId} kind="tariff-types" value={row.tariff_type_id} disabled={locked} onselect={id=>row.tariff_type_id=id}/></td><td><input type="date" disabled={locked} bind:value={row.date}/></td><td><select disabled={locked} bind:value={row.active}><option value={true}>{t('Подключена','Conectat')}</option><option value={false}>{t('Не подключена','Deconectat')}</option></select></td></tr>{/each}
 {:else if tab==='residents'}{#each draft.resident_rows||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td><td><AccountLookupField {project} parentId={editorId} kind="citizens" value={row.citizen_id} disabled={locked} onselect={id=>row.citizen_id=id}/></td><td><select disabled={locked} bind:value={row.registration}>{#each [1,2,3] as code}<option value={code}>{statusLabel(code,'registration',project.settings.language==='ro')}</option>{/each}</select></td><td><select disabled={locked} bind:value={row.residence}>{#each [1,2,3] as code}<option value={code}>{statusLabel(code,'residence',project.settings.language==='ro')}</option>{/each}</select></td><td><input type="date" disabled={locked} bind:value={row.from}/></td><td><input type="date" disabled={locked} value={row.to||''} onchange={e=>row.to=e.currentTarget.value||null}/></td></tr>{/each}
 {:else if tab==='additional'}{#each draft.additional_rows||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td><td><AccountLookupField {project} parentId={editorId} kind="properties" value={row.property_id} disabled={locked} onselect={id=>row.property_id=id}/></td><td><select disabled={locked} bind:value={row.active}><option value={true}>{t('Подключён','Conectat')}</option><option value={false}>{t('Не подключён','Deconectat')}</option></select></td></tr>{/each}
 {:else if tab==='balances'}{#each draft.balance_rows||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td><td><AccountLookupField {project} parentId={editorId} kind="services" value={row.service_id} disabled={locked} onselect={id=>row.service_id=id}/></td><td><input disabled={locked} bind:value={row.amount}/></td><td><input disabled={locked} bind:value={row.penalty}/></td></tr>{/each}
 {:else if tab==='readings'}{#each draft.initial_readings||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td><td><select disabled={locked} bind:value={row.meter_id}><option value="">—</option>{#each project.meters.filter(m=>m.account_id===draft!.account.id&&m.scope==='individual') as meter}<option value={meter.id}>{meter.label}</option>{/each}</select></td><td><input disabled={locked} bind:value={row.value}/></td><td><input type="date" disabled={locked} bind:value={row.date}/></td></tr>{/each}
 {:else}{#each draft.characteristic_rows||[] as row,i}<tr class:selected={selectedRow===row.id} onclick={()=>selectedRow=row.id}><td>{i+1}</td><td><input disabled={locked} bind:value={row.name}/></td><td><input disabled={locked} bind:value={row.value}/></td></tr>{/each}{/if}
 </tbody></table></div>{/if}
 <label class="field comment"><span>{t('Комментарий:','Comentariu:')}</span><input disabled={locked} bind:value={draft.comment}/></label><footer><button class="button secondary movements" disabled={!project.account_documents.some(d=>d.id===draft!.id)} onclick={()=>draft&&onmovements(draft)}><FileText size={16}/>{t('Движения','Înregistrări')}</button>{#if !locked}<button class="button" onclick={()=>save(true,true)}><Check size={16}/>OK</button><button class="button secondary" onclick={()=>save()}><Save size={16}/>{t('Сохранить','Salvează')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>
{/if}</div>
<style>.account-documents{display:flex;flex-direction:column;gap:12px;padding:14px;min-width:0}fieldset{border:0;margin:0;padding:0;min-width:0;display:flex;flex-direction:column;gap:14px}.document-date{display:flex;gap:20px;align-items:center;flex-wrap:wrap}.document-date label{display:flex;gap:10px;align-items:center}.document-date input:not([type=date]){width:100px}.field{display:grid;grid-template-columns:170px minmax(0,1fr);gap:12px;align-items:center}.field>input{width:100%;box-sizing:border-box;min-width:0}.resident-flags{display:flex;justify-content:flex-end;gap:20px}.check-row{display:flex;gap:8px;align-items:center}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field-grid label{display:flex;flex-direction:column;gap:6px}.field-grid input{min-width:0}.tabs{display:flex;gap:2px;flex-wrap:wrap;border-bottom:1px solid var(--border)}.tabs button{background:transparent;color:var(--text);border:0;padding:9px}.tabs button.chosen{box-shadow:inset 0 -2px var(--accent);background:var(--hover)}.table-wrap{max-height:52vh;overflow:auto;min-width:0}table{width:100%;border-collapse:collapse}th,td{padding:7px;text-align:left}th{position:sticky;top:0;background:var(--surface);font-weight:600;z-index:1}td input,td select{min-width:90px;max-width:180px;box-sizing:border-box}td :global(.lookup-field){min-width:160px}tr.selected{background:#489bcb30}tr.marked{opacity:.6;text-decoration:line-through}.comment{margin-top:auto}footer{display:flex;justify-content:flex-end;gap:8px;padding-top:12px}.movements{margin-right:auto}</style>
